import{_ as p}from"./C6gRvd95.js";import{m as g,f as y,c as s,a as o,g as w,n as f,k,t as b,u as t,o as l}from"./CBnRMYeL.js";import{u as v}from"./BKCGliV8.js";const S={class:"section-padding"},T={class:"container thinnest-content"},_={class:"mb-3"},I=["src"],x={__name:"to-whom-it-may-inspire",setup(P){const h=g(),{currentRoute:d}=h,e=y.find(a=>a.slug===d.value.fullPath.replace("/articles/",""));let i=`${e.title}`,n=`${e.description}`,u=`Stefan, Stefan Auvache Bradley, Bradley, ${e.categories.join(", ")}, ${e.keywords}`,c=`www.stefanauvache.com/articles/${e.slug}`;return v({title:i,ogTitle:i,description:n,ogDescription:n,keywords:u,canonical:c,robots:"index, follow"}),(a,r)=>{const m=p;return l(),s("section",S,[o("div",T,[o("div",null,[o("h1",_,b(t(e).title),1),t(e).image!=="title.jpg"?(l(),s("img",{key:0,src:`/img/articles/${t(e).image}`,alt:"",class:"mb-3"},null,8,I)):f("",!0),r[0]||(r[0]=k('<p>We often overestimate what we can do in a day and underestimate what we can do in a decade. On the day-to-day, progress can seem painstakingly slow, and it can be incredibly disheartening to compare ourselves to the people we wish we were. Whether you’ve been writing a book, working on a bachelor’s degree, or learning to play an instrument, it is easy to feel like the task at hand is insurmountable. Widen your lens, lengthen your timeline. Stick with it. All experts in the world were once beginners. Provided you are open to feedback and are doing your work, you will improve, and improvement is compounded over time.</p><p>No one becomes successful overnight. Stephen King wrote for almost ten years before publishing his first book. For Steven Pressfield, it was closer to thirty. Samuel L. Jackson was an actor for twenty years before his breakout role in Pulp Fiction. Usain Bolt missed his first Olympic Games due to injury. People find success when they do their work and keep doing it. They work on the good days and they work on the bad days. They work when things are going right and they work when things are going horribly wrong.</p><p>“How many pages have I produced?” asks Steven Pressfield of himself. “I don’t care. Are they any good? I don’t even think about it. All that matters is I’ve put in my time and hit it with all I’ve got… The most important thing about art is to work. Nothing else matters except sitting down every day and trying.”</p><p>In 2011, after contributing to several successful films (Ratatouille, WALL-E, Up, and Toy Story 3 to name a few), Pixar animator Austin Madison wrote the following letter to fellow creators going through hard times.</p><div class="quote mb-3"><p>To Whom it May Inspire,</p><p>I, like many of you artists out there, constantly shift between two states. The first (and far more preferable of the two) is white-hot, “in the zone” seat-of-the-pants, firing on all cylinders creative mode. This is when you lay your pen down and the ideas pour out like wine from a royal chalice! This happens about 3% of the time.</p><p>The other 97% of the time I am in the frustrated, struggling, office-corner-full-of-crumpled-up-paper mode. The important thing is to slog diligently through this quagmire of discouragement and despair. Put on some audio commentary and listen to the stories of professionals who have been making films for decades going through the same slings and arrows of outrageous production problems.</p><p>In a word: PERSIST.</p><p>PERSIST on telling your story. PERSIST on reaching your audience. PERSIST on staying true to your vision. Remember what Peter Jackson said, “Pain is temporary. Film is forever.” And he of all people should know.</p><p>So next time you hit writer’s block, or your computer crashes and you lose an entire night’s work because you didn’t hit save (always hit save), just remember: you’re never far from that next burst of divine creativity. Work through that 97% of murky abysmal mediocrity to get to that 3% which everyone will remember you for!</p><p>I guarantee you, the art will be well worth the work!</p><p>Your friend and mine,</p><p>Austin Madison</p><p>“ADVENTURE IS OUT THERE!”</p></div><p>Persist. Things will not always be easy. Things will not always be so hard. Do your work and keep doing it. On a long enough timeline, anyone can do almost anything.</p>',6))]),w(m,{slug:t(e).slug},null,8,["slug"])])])}}};export{x as default};
